def string_matching(words):
    sorted_words = sorted(words, key=len)                    # shortest words first
    result = []
    for i in range(len(sorted_words)):
        for j in range(i + 1, len(sorted_words)):                # only compare against strictly longer words
            if sorted_words[i] in sorted_words[j]:
                result.append(sorted_words[i])
                break
    return result


if __name__ == "__main__":
    words = ["mass", "as", "hero", "superhero"]
