vector<string> stringMatching(vector<string>& words) {
    vector<string> sortedWords = words;
    stable_sort(sortedWords.begin(), sortedWords.end(), [](const string& a, const string& b) {
        return a.size() < b.size();                                       // shortest words first
    });
    vector<string> result;
    for (int i = 0; i < (int)sortedWords.size(); i++) {
        for (int j = i + 1; j < (int)sortedWords.size(); j++) {              // only compare against strictly longer
            if (sortedWords[j].find(sortedWords[i]) != string::npos) {
                result.push_back(sortedWords[i]);
                break;
            }
        }
    }
    return result;
}

